import{_ as o,o as e,c as r,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Songs of Silence (2024) — 게임 로직 백과사전","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-Songs-of-Silence.md","filePath":"rules/Ref-Songs-of-Silence.md"}'),n={name:"rules/Ref-Songs-of-Silence.md"};function i(a,t,l,g,d,c){return e(),r("div",null,[...t[0]||(t[0]=[s('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(<code>songs-of-silence.md</code>)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다. 실측·판독 기준일 2026-09-07.</p></blockquote><h1 id="songs-of-silence-2024-—-게임-로직-백과사전" tabindex="-1">Songs of Silence (2024) — 게임 로직 백과사전 <a class="header-anchor" href="#songs-of-silence-2024-—-게임-로직-백과사전" aria-label="Permalink to &quot;Songs of Silence (2024) — 게임 로직 백과사전&quot;">​</a></h1><blockquote><p>Chimera Entertainment, 2024-11-13 (PC·PS5·Xbox Series). 한국·일본 퍼블리셔 H2 Interactive. 아르누보 화풍의 판타지 세계에서 여왕 로렐라이의 유민을 이끄는 <strong>턴제 4X 전략 지도 + 실시간 자동 전투 + 영웅 카드 개입</strong> 하이브리드. 본편 1.0 기준, DLC 제외. 조사 기준일: 2026-09-07.</p><p><strong>표기</strong>: <code>[문서]</code>는 열람한 공식 스토어 데이터·리뷰·위키의 내용, <code>[추론]</code>은 그 자료를 종합한 구조 해석, <code>[미확인]</code>은 자료가 차단되거나 수치가 공개되지 않아 확정하지 못한 내용이다. 출처 S-ID는 문서 말미 목록 참조.</p><p><strong>이 문서가 존재하는 이유</strong>: 2026-09-07 소유자가 잔선의 전투를 &quot;턴제 SRPG가 아니라 <strong>실시간·진형·카드 기반</strong>&quot;으로, 게임 전체를 &quot;<strong>4X + RPG</strong>&quot;로 규정하며 이 게임을 목표 형태로 지목했다(<a href="https://github.com/islee23520/seoul-kenshi/blob/main/Intent.md" target="_blank" rel="noreferrer">Intent.md</a> 결정 3). 이 문서는 그 목표 형태를 검증 가능한 사실로 고정한다.</p></blockquote><h2 id="_1-개요" tabindex="-1">1. 개요 <a class="header-anchor" href="#_1-개요" aria-label="Permalink to &quot;1. 개요&quot;">​</a></h2><ul><li><strong>장르 정체</strong>: 스토어 장르 태그는 Adventure·Indie·RPG·Simulation·Strategy. 싱글 캠페인 8맵, 온라인 PvP·협동, 풀 컨트롤러 지원, 난이도 조절·마우스 전용·시간제한 입력 없음 접근성 옵션. 메타크리틱 81, Steam 추천 2,362건(2026-09-07 조회). [S-01][문서]</li><li><strong>두 층 구조</strong>: 넓은 4X 층(격자 없는 지도에서 군대 이동·정착지 점령·업그레이드·시야 개방)과 좁은 교전 층(RTS식 자동 전투, 일시정지 후 카드 사용, 한쪽이 궤주·전멸할 때까지). [S-03][문서]</li><li><strong>자동 전투의 정의</strong>: 전투가 시작되면 부대는 자동으로 싸우고, 플레이어는 개별 유닛을 조작하지 않는다. 대신 <strong>전투 전 편성·배치</strong>와 <strong>전투 중 카드 타이밍</strong>이 입력이다. 자동 해결(auto-resolve)은 없다. [S-02][S-04][문서]</li><li><strong>세 세력</strong>: 문화·외교·교역 / 신성 정복·무용 / 기술·실험. 세력 정체성이 이야기 사건·유닛·영웅 카드 설계에 스며 있다. [S-05][문서]</li><li><strong>비판 지점</strong>: 카드가 사소해 전투 결과가 <strong>전투 전 수치·위치 우위</strong>로 거의 정해진다는 평(Game8), 중반 페이스 지연·AI 반복성·카드 랜덤 드로우가 계획을 희석한다는 평(Drastik). [S-03][S-05][문서]</li></ul><h2 id="_2-코어-루프" tabindex="-1">2. 코어 루프 <a class="header-anchor" href="#_2-코어-루프" aria-label="Permalink to &quot;2. 코어 루프&quot;">​</a></h2><ol><li><strong>지도 턴</strong>: 군대를 이동해 정착지를 점령하고 경제·모집을 키운다. 정착지는 전문화(성벽 유무·수비대 생성)와 자원 산출률이 다르다. [S-02][문서]</li><li><strong>거점 관리</strong>: 우호 거점 안에서 유닛 구매, 베테랑 업그레이드, <strong>예비대</strong>(동행하되 전투에 불참) 관리, 수비대 배정. [S-03][문서]</li><li><strong>접촉 → 편성</strong>: 적 부대를 공격하기 전에 아군 배치를 재정렬한다(적 우익이 보병을 잡아먹는 괴수라면 기병을 맞세우는 식). [S-02][문서]</li><li><strong>실시간 자동 전투</strong>: 일시정지 가능. 영웅 카드로 기병 돌격·치유·소환·광역 피해·상태 효과를 건다. [S-03][S-04][문서]</li><li><strong>정산과 성장</strong>: 영웅은 매 교전 후 복귀(소모품이 아님), 레벨업으로 카드가 강화·해금된다. [S-03][문서]</li></ol><p>결정 지점은 세 곳 — <strong>지도에서 어디를 칠 것인가, 전투 전에 누구를 어디에 세울 것인가, 전투 중 어느 카드를 언제 낼 것인가</strong>. [추론]</p><h2 id="_3-4x-층" tabindex="-1">3. 4X 층 <a class="header-anchor" href="#_3-4x-층" aria-label="Permalink to &quot;3. 4X 층&quot;">​</a></h2><ul><li><strong>자원 3종</strong>: 골드(모집), 자재(주로 건설), 세력 고유 마법 자원. [S-02][문서]</li><li><strong>정착지 1건물</strong>: 정착지마다 건물 하나만 세우며, 건설 가능 목록은 <strong>영웅 레벨업으로 해금</strong>한 유형에 종속된다. [S-02][문서]</li><li><strong>경량 4X</strong>: 4X·TBS 어느 것보다 단순하다는 평. 확장은 &quot;제국 건설&quot;보다 <strong>고립 지역 통제</strong> 위주(Game8이 약점으로 지적). [S-02][S-03][문서]</li><li><strong>지도 옵션</strong>: 크기 S/M/L, 배치 2종(1-sided …). [S-01][문서] 정확한 배치 종류명은 스토어 텍스트가 잘려 [미확인].</li><li><strong>탐사 보상</strong>: 8개 캠페인 맵이 매우 크고, 지도의 절반을 건너뛰어도 승리 가능 — 샛길의 정착지·전승·유물이 탐사 동기. [S-02][문서]</li><li><strong>매복</strong>: 위키 요약은 &quot;치명적인 매복 설치&quot;를 특징으로 든다. [S-06][문서(스니펫)] 구체 규칙은 [미확인].</li></ul><h2 id="_4-유닛-모델-—-두-수치와-특성" tabindex="-1">4. 유닛 모델 — 두 수치와 특성 <a class="header-anchor" href="#_4-유닛-모델-—-두-수치와-특성" aria-label="Permalink to &quot;4. 유닛 모델 — 두 수치와 특성&quot;">​</a></h2><ul><li><strong>기본 수치 2개</strong>: HP와 <strong>파워(power)</strong>. 파워 하나가 공격력과 방어력을 겸한다. [S-02][문서]</li><li><strong>특성이 나머지를 결정</strong>: Armor(피해 전부를 회피할 확률), Annihilate(한 타격에 1 이상의 피해), 대상별 Slayer 특성, 보병을 먹어 회복하는 괴수, 돌격 기병, 원거리 소환사·마법사, 피해 편향 등. [S-02][S-03][문서]</li><li><strong>설계 철학</strong>: &quot;토탈 워를 20개 스탯 대신 2개 스탯으로 하고 특성이 나머지를 처리하는 것&quot; — 의미 없는 스탯 줄 대신 특성 조합으로 깊이를 낸다. [S-02][문서]</li><li><strong>로스터 규모</strong>: 100종 이상 유닛. [S-06][문서(스니펫)]</li><li><strong>영웅</strong>: 고유 능력·카드 보유, 교전 후 항상 귀환, 레벨업 시 카드 강화. [S-03][문서]</li></ul><h2 id="_5-진형과-실시간-전투" tabindex="-1">5. 진형과 실시간 전투 <a class="header-anchor" href="#_5-진형과-실시간-전투" aria-label="Permalink to &quot;5. 진형과 실시간 전투&quot;">​</a></h2><ul><li><strong>배치가 입력</strong>: 전투 전 부대 재정렬이 플레이어의 주된 전술 행위. 좌우익·전면 편성으로 적 조합에 대응. [S-02][문서]</li><li><strong>실시간 진행 + 일시정지</strong>: 전투 중 일시정지해 명령(카드)을 낸다. 편성 관리도 실시간이라는 표현(Drastik). [S-03][S-05][문서]</li><li><strong>종료 조건</strong>: 한쪽이 <strong>궤주(routed)</strong> 또는 전멸. 도망치는 궁병을 보병이 쫓는 데 시간이 걸릴 수 있다. [S-02][S-03][문서]</li><li><strong>회복 경제</strong>: 전투 중 카드로 되살리거나 치유한 병사는 정착지 보급(드문 기능)이나 유료 전략 카드 없이 대열에 복귀한다 — 카드가 곧 병력 보존. [S-02][문서]</li><li>진형의 격자 형태·열 수·부대 슬롯 수는 [미확인].</li></ul><h2 id="_6-카드-시스템" tabindex="-1">6. 카드 시스템 <a class="header-anchor" href="#_6-카드-시스템" aria-label="Permalink to &quot;6. 카드 시스템&quot;">​</a></h2><ul><li><strong>카드의 정의</strong>: 덱 구축·핸드 드로우가 아니라 <strong>영웅과 장소가 부여하는 고유 행동</strong>. 캠페인 지도 또는 실시간 전투에서 부대 명령·상태 효과·직접 피해로 결과에 개입한다. [S-06][문서(스니펫)]</li><li><strong>두 맥락</strong>: 전략 카드(지도 — 군대 강화, 구조물 건설, 유닛 모집), 전술 카드(전장 — 광역 피해, 전 기병에게 특정 지점 돌격 명령 등). &quot;조금이라도 대등한 전투에서는 카드가 승리의 열쇠&quot;. [S-02][문서]</li><li><strong>재충전</strong>: 로렐라이의 Divine Spark(치유·부활)는 재충전 타이머가 허용하는 한 여러 번 사용. [S-02][문서]</li><li><strong>트리거 카드</strong>: 앞선 능력 사용 후에만 발동하는 조건부 카드가 장기 시너지를 보상. [S-05][문서]</li><li><strong>랜덤성</strong>: 카드 드로우에 무작위성이 있어 콤보가 불발될 수 있다는 평. [S-05][문서] 드로우 규칙·핸드 크기·비용 자원은 [미확인].</li><li><strong>평가의 양면</strong>: &quot;각 영웅이 다르게 느껴지는 가장 즐거운 부분&quot;(indiegames.wtf) vs &quot;카드가 사소해 전투가 정적&quot;(Game8). [S-03][S-04][문서]</li><li>개발 일지 #1 「Cards of Faith」(2023-04-16, ModDB/Steam)가 카드 체계의 1차 출처이나 이번 조사에서 본문 열람이 차단됐다. [S-08][미확인]</li></ul><h2 id="_7-캠페인·진행" tabindex="-1">7. 캠페인·진행 <a class="header-anchor" href="#_7-캠페인·진행" aria-label="Permalink to &quot;7. 캠페인·진행&quot;">​</a></h2><ul><li>8개 스토리 캠페인 맵, 3단계 난이도(이야기 모드 캐주얼 ~ 상위 난이도 전용 도전과제·퀘스트), 사이드 퀘스트·비밀. [S-01][문서]</li><li>분기 경로·세력 엔딩·영웅 관계가 초반 결정으로 크게 달라지고, **New Game+**로 카드·업그레이드·대체 분기 이월. [S-05][문서]</li><li>콘텐츠 해금이 도전과제에 묶여 초반 선택지가 제한된다는 불만. [S-05][문서]</li><li>튜토리얼은 시스템을 점진적으로 풀어 4X 비숙련자도 진입 가능. [S-04][문서]</li></ul><h2 id="_8-잔선-적용-소유자-방향-2026-09-07" tabindex="-1">8. 잔선 적용 (소유자 방향 2026-09-07) <a class="header-anchor" href="#_8-잔선-적용-소유자-방향-2026-09-07" aria-label="Permalink to &quot;8. 잔선 적용 (소유자 방향 2026-09-07)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Songs of Silence</th><th>잔선에서의 형태</th><th>판단</th></tr></thead><tbody><tr><td>지도 턴 + 실시간 자동 전투 두 층</td><td>전략 노선도·역간 여행은 확정 명령 단위, 전투는 실시간 틱 시뮬레이션</td><td>채택 — 세 표면 구조 유지</td></tr><tr><td>두 수치(HP·파워) + 특성</td><td>인물 스탯은 유지하되 <strong>전투 판정은 소수 파생 수치 + 특성</strong>으로 압축</td><td>채택 후보 — 라벨렌식 9스탯 공식과 비교 후 결정</td></tr><tr><td>전투 전 배치 = 주 입력</td><td>진형 편집(전열·후열·측면, 4방향 정면)이 출격 준비의 핵심 화면</td><td>채택</td></tr><tr><td>영웅·장소 카드, 전략/전술 두 맥락</td><td><strong>인물 카드</strong>(관계·생업·특기)와 <strong>거점 카드</strong>(보급·통행권·설비)</td><td>채택 — 덱 구축 없음, 부여형</td></tr><tr><td>일시정지 후 카드</td><td>일시정지 허용, 카드 플레이는 틱 스탬프 명령으로 원장에 기록</td><td>채택 — 결정론 계약 유지</td></tr><tr><td>카드 부활·치유 = 병력 보존 경제</td><td>부상 이행 계약과 충돌 — 잔선은 <strong>쓰러짐 방지·후송</strong>까지만</td><td>부분 채택</td></tr><tr><td>궤주 종료</td><td>사기 붕괴 → 궤주·항복(라벨렌 3조건과 결합)</td><td>채택</td></tr><tr><td>카드 랜덤 드로우</td><td>채택하지 않음 — 카드는 부여·재충전형, 드로우 없음</td><td>거부(투명성 원칙)</td></tr><tr><td>자동 해결 없음</td><td>소규모 조우는 예측 표시 후 즉시 정산 허용</td><td>부분 거부(시간 = 비용 원칙)</td></tr><tr><td>경량 4X(자원 3종·정착지 1건물)</td><td>16국 노선 경제는 이미 별도 설계 — 4X 골격은 유지하되 단순화 정도는 별도 결정</td><td>보류</td></tr></tbody></table><h2 id="부록-출처" tabindex="-1">부록. 출처 <a class="header-anchor" href="#부록-출처" aria-label="Permalink to &quot;부록. 출처&quot;">​</a></h2><ul><li><strong>S-01</strong> Steam Store appdetails API, appid 2195410 (cc=us, l=english), 2026-09-07 조회 — 이름·발매일·개발/퍼블리셔·장르·카테고리·가격·메타크리틱·소개문·스크린샷 10장.</li><li><strong>S-02</strong> Turn Based Lovers, &quot;Songs of Silence: Autobanishing the horrors – Review&quot; (2024-12), <a href="https://turnbasedlovers.com/review/songs-of-silence-autobanishing-the-horrors-impressions/" target="_blank" rel="noreferrer">https://turnbasedlovers.com/review/songs-of-silence-autobanishing-the-horrors-impressions/</a> — 자원 3종, 정착지 1건물, HP·파워·특성, 편성 재정렬, 전략/전술 카드, Divine Spark 재충전, 자동 해결 없음, 8맵 규모.</li><li><strong>S-03</strong> Game8, &quot;Songs of Silence Review | As Beautiful and Boring as Ever&quot;, <a href="https://game8.co/reviews/songs-of-silence/songs-of-silence-review" target="_blank" rel="noreferrer">https://game8.co/reviews/songs-of-silence/songs-of-silence-review</a> — 두 층 구조, 일시정지 카드, 궤주/전멸 종료, 거점 관리(예비대·수비대), 영웅 귀환·카드 강화, 카드 영향력 비판.</li><li><strong>S-04</strong> indiegames.wtf, &quot;Songs of Silence&quot; review, <a href="https://indiegames.wtf/reviews/songs-of-silence/" target="_blank" rel="noreferrer">https://indiegames.wtf/reviews/songs-of-silence/</a> — 턴제 지도·실시간 자동 전투·카드 개입·준비/편성/타이밍 중심.</li><li><strong>S-05</strong> The Drastik Measure, &quot;Songs of Silence – PC Review&quot; (2025-12-17), <a href="https://www.thedrastikmeasure.com/2025/12/17/songs-of-silence-pc-review/" target="_blank" rel="noreferrer">https://www.thedrastikmeasure.com/2025/12/17/songs-of-silence-pc-review/</a> — 세 세력 정체성, 실시간 편성·일시정지, 트리거 카드, 카드 RNG, NG+, 분기.</li><li><strong>S-06</strong> Songs of Silence Wiki (Fandom) &quot;Cards&quot;·메인 페이지, <a href="https://songs-of-silence.fandom.com/wiki/Cards" target="_blank" rel="noreferrer">https://songs-of-silence.fandom.com/wiki/Cards</a> — 검색 결과 스니펫만 확보(본문은 Cloudflare 차단). 카드 정의·100종 유닛·매복.</li><li><strong>S-07</strong> Steam Community 게임 허브 요약, <a href="https://steamcommunity.com/games/2195410" target="_blank" rel="noreferrer">https://steamcommunity.com/games/2195410</a> — &quot;turn-based strategy mixed with auto-battler mechanics and real-time card tactics&quot; (스니펫).</li><li><strong>S-08</strong> ModDB, &quot;Dev diary #1 — Cards of Faith&quot; (2023-04-16), <a href="https://www.moddb.com/games/songs-of-silence/news/dev-diary-1-cards-of-faith" target="_blank" rel="noreferrer">https://www.moddb.com/games/songs-of-silence/news/dev-diary-1-cards-of-faith</a> — 제목·요약만 확인, 본문 차단. [미확인]</li></ul>',23)])])}const S=o(n,[["render",i]]);export{u as __pageData,S as default};
